export class TextStats{static words(t){const a=String(t||"").match(/[\p{L}\p{N}'’-]+/gu);return a?a.length:0}static sentences(t){return String(t||"").split(/(?<=[.!?…])["'”’)\]]*\s+|\n{2,}/u).map(t=>t.trim()).filter(t=>t.length>1)}static paragraphs(t){return String(t||"").split(/\n{2,}|\n(?=\s{2,})/).map(t=>t.trim()).filter(Boolean)}static syllables(t){const a=String(t).toLowerCase().replace(/[^a-z]/g,"");if(!a)return 0;const e=a.match(/[aeiou]+/g);return Math.max(1,e?e.length:1)}static readability(t){const a=TextStats.words(t);if(!a)return 0;const e=TextStats.sentences(t).length||1,s=(String(t||"").match(/[\p{L}]+/gu)||[]).reduce((t,a)=>t+TextStats.syllables(a),0);return Math.max(0,Math.min(100,Math.round(206.835-a/e*1.015-s/a*65.14)))}static freq(t,{min:a=3,stop:e=!0}={}){const s=(String(t||"").toLowerCase().match(/[\p{L}'’-]+/gu)||[]).filter(t=>t.length>=a&&(!e||!TextStats.STOP.has(t))),n=new Map;for(const t of s)n.set(t,(n.get(t)||0)+1);return[...n.entries()].map(([t,a])=>({word:t,count:a})).sort((t,a)=>a.count-t.count)}static dialogueRatio(t){const a=TextStats.sentences(t);return a.length?a.filter(t=>/^["“”']|["“”]$/.test(t.trim())).length/a.length:0}static readingMinutes(t,a=220){return Math.max(1,Math.round(t/a))}static stats(t){const a=String(t||""),e=TextStats.words(a),s=TextStats.sentences(a),n=TextStats.paragraphs(a);return{words:e,chars:a.replace(/\s/g,"").length,sentences:s.length,paragraphs:n.length,avgSentence:s.length?Math.round(e/s.length*10)/10:0,avgParagraph:n.length?Math.round(e/n.length):0,readability:TextStats.readability(a),dialogue:TextStats.dialogueRatio(a),minutes:TextStats.readingMinutes(e),pages:Math.max(1,Math.round(e/275)),longest:s.reduce((t,a)=>Math.max(t,TextStats.words(a)),0)}}static summarize(t,a=3){const e=TextStats.sentences(t);if(e.length<=a)return e.join(" ");const s=new Map(TextStats.freq(t,{min:4}).map(t=>[t.word,t.count]));return e.map((t,a)=>{const e=t.toLowerCase().match(/[\p{L}]+/gu)||[];return{s:t,i:a,score:e.reduce((t,a)=>t+(s.get(a)||0),0)/Math.max(6,e.length)+(0===a?1.2:0)}}).sort((t,a)=>a.score-t.score).slice(0,a).sort((t,a)=>t.i-a.i).map(t=>t.s).join(" ")}static titleCase(t){return String(t||"").replace(/\w\S*/g,t=>t[0].toUpperCase()+t.slice(1).toLowerCase())}static excerpt(t,a=160){const e=String(t||"").replace(/\s+/g," ").trim();return e.length<=a?e:`${e.slice(0,a-1)}…`}}TextStats.STOP=new Set("yang dan di ke dari untuk dengan pada adalah itu ini tidak akan saya aku kamu dia mereka kita sudah telah bisa dapat juga atau tapi tetapi karena jika saat ketika ada oleh dalam sebagai lebih hanya saja masih harus nya lah kah pun para sebuah seorang satu dua agar supaya begitu seperti antara setelah sebelum lalu kemudian namun maka hingga sampai tanpa bukan belum sedang the a an of to in and".split(/\s+/));